/**
 * AI Assist contracts — single source of truth for AI job RPC signatures + types.
 *
 * S24 scaffold. Dato's migration must produce RPCs matching these exact param names.
 * If drift occurs, runtime 500s appear immediately — catch early with pnpm typecheck.
 *
 * Invariant: "never sends autonomously" — AiDraftStatus 'sent' is only reachable
 * after 'approved'. Enforced in assertValidDraftTransition() + Luna tests.
 */

// ---------------------------------------------------------------------------
// Discriminated union string literals
// ---------------------------------------------------------------------------

export type AiJobType = 'reply_draft' | 'consult_summary' | 'aftercare_gen'
export type AiJobStatus = 'pending' | 'processing' | 'done' | 'failed' | 'cancelled'
export type AiDraftType = 'reply' | 'consult_summary' | 'aftercare'
export type AiDraftStatus = 'pending' | 'approved' | 'discarded' | 'sent'

// ---------------------------------------------------------------------------
// Draft state machine — never-autonomous invariant
// ---------------------------------------------------------------------------

/**
 * Legal transitions for ai_drafts.status.
 * 'discarded' and 'sent' are terminal — no exits.
 * The path pending → sent requires an approved intermediate step.
 */
export const DRAFT_TRANSITION_RULES: Record<AiDraftStatus, readonly AiDraftStatus[]> = {
  pending:   ['approved', 'discarded'],
  approved:  ['sent', 'discarded'],
  discarded: [],
  sent:      [],
} as const

/**
 * Assert that a draft status transition is legal.
 * Throws if the transition violates the never-autonomous invariant.
 * Tested by Luna — export is required.
 */
export function assertValidDraftTransition(from: AiDraftStatus, to: AiDraftStatus): void {
  const allowed = DRAFT_TRANSITION_RULES[from] as readonly string[]
  if (!allowed.includes(to)) {
    throw new Error(
      `Invalid AI draft transition: ${from} → ${to}. Never-autonomous invariant violated.`,
    )
  }
}

// ---------------------------------------------------------------------------
// RPC: get_studio_ai_budget_usage
// ---------------------------------------------------------------------------

export interface AiBudgetUsageArgs {
  p_studio_id: string
  /** Number of days to aggregate. Default 1 (today UTC). */
  p_days?: number
}

export interface AiBudgetUsageResult {
  total_cost_cents: number
  cap_cents: number               // 500 per day × p_days
  budget_remaining_cents: number
  days: number
  job_count: number
}

// ---------------------------------------------------------------------------
// RPC: record_ai_cost
// ---------------------------------------------------------------------------

export interface RecordAiCostArgs {
  p_studio_id: string
  p_job_id: string
  p_job_type: AiJobType
  p_model: string
  p_input_tokens: number
  p_output_tokens: number
  p_cost_cents: number            // always integer cents
}

export type RecordAiCostResult = { id: string }

// ---------------------------------------------------------------------------
// RPC name constants — avoids magic strings at call sites
// ---------------------------------------------------------------------------

export const AI_RPC = {
  GET_AI_BUDGET_USAGE: 'get_studio_ai_budget_usage',
  RECORD_AI_COST:      'record_ai_cost',
} as const

// Convenience alias for callers that want the union of RPC names
export type AiRpcName = (typeof AI_RPC)[keyof typeof AI_RPC]

/**
 * AI daily budget enforcement — per Arya integration spec §2.3.
 *
 * Cap: $5/studio/day (500 cents). Checked against ai_design_outputs.cost_cents sum
 * (legacy) or the new get_studio_ai_budget_usage RPC (S24+).
 *
 * requireAiBudget     — original, queries ai_design_outputs (Sprint 9 AI Design).
 * requireAiAssistBudget — S24: queries AI Assist RPC with fallback to legacy table.
 * recordAiCost        — S24: writes ai_costs via service-role RPC.
 *
 * Throws AiBudgetExceededError if the estimated cost would exceed the daily cap.
 */
import 'server-only'
import type { SupabaseClient } from '@supabase/supabase-js'
import { logger } from '@/lib/logger'
import {
  AI_RPC,
  type AiBudgetUsageArgs,
  type AiBudgetUsageResult,
  type RecordAiCostArgs,
  type RecordAiCostResult,
} from './contracts'

const DAILY_CAP_CENTS_PER_STUDIO = 500 // $5/day

// ---------------------------------------------------------------------------
// Error class (unchanged — preserved for all callers)
// ---------------------------------------------------------------------------

export class AiBudgetExceededError extends Error {
  readonly code = 'ai_budget_exceeded'

  constructor(
    public readonly studioId: string,
    public readonly usedCents: number,
    public readonly capCents: number,
  ) {
    super(`studio ${studioId} exceeded daily AI budget ($${capCents / 100})`)
    this.name = 'AiBudgetExceededError'
    Object.setPrototypeOf(this, AiBudgetExceededError.prototype)
  }
}

// ---------------------------------------------------------------------------
// Original budget check (Sprint 9 AI Design — DO NOT remove)
// ---------------------------------------------------------------------------

/**
 * Check whether the studio has budget remaining for an AI call.
 * Throws AiBudgetExceededError if cap would be exceeded.
 *
 * @param supabase — authenticated or service-role client
 * @param studioId — scoped per studio
 * @param estimatedCostCents — integer cents for the planned call
 */
export async function requireAiBudget(
  supabase: SupabaseClient,
  studioId: string,
  estimatedCostCents: number,
): Promise<void> {
  const todayUtcStart = new Date()
  todayUtcStart.setUTCHours(0, 0, 0, 0)

  const { data, error } = await supabase
    .from('ai_design_outputs')
    .select('cost_cents')
    .eq('studio_id', studioId)
    .gte('created_at', todayUtcStart.toISOString())

  if (error) throw new Error(`AI budget check failed: ${error.message}`)

  const usedToday = (data ?? []).reduce((s, r) => s + (r.cost_cents ?? 0), 0)

  if (usedToday + estimatedCostCents > DAILY_CAP_CENTS_PER_STUDIO) {
    throw new AiBudgetExceededError(studioId, usedToday, DAILY_CAP_CENTS_PER_STUDIO)
  }
}

// ---------------------------------------------------------------------------
// S24: AI Assist budget check (uses new RPC, falls back to legacy table)
// ---------------------------------------------------------------------------

/**
 * Check AI Assist budget for a studio.
 * Primary path: calls get_studio_ai_budget_usage RPC (Dato S24 migration).
 * Fallback: queries ai_design_outputs directly (defensive — RPC may not be deployed in CI).
 *
 * Throws AiBudgetExceededError if budget_remaining_cents <= 0 after estimated cost.
 *
 * @returns { remaining, capCents } — callers can include in structured logs.
 */
export async function requireAiAssistBudget(
  supabase: SupabaseClient,
  studioId: string,
  estimatedCostCents: number,
): Promise<{ remaining: number; capCents: number }> {
  // ── Primary: new RPC ────────────────────────────────────────────────────
  const rpcArgs: AiBudgetUsageArgs = { p_studio_id: studioId, p_days: 1 }
  const { data: rpcData, error: rpcError } = await supabase
    .rpc(AI_RPC.GET_AI_BUDGET_USAGE, rpcArgs)

  if (!rpcError && rpcData !== null) {
    // Supabase .rpc() returns a single row result for scalar RPCs
    const result = rpcData as AiBudgetUsageResult
    const remaining = result.budget_remaining_cents - estimatedCostCents

    if (remaining < 0) {
      throw new AiBudgetExceededError(
        studioId,
        result.cap_cents - result.budget_remaining_cents,
        result.cap_cents,
      )
    }

    return { remaining, capCents: result.cap_cents }
  }

  // ── Fallback: legacy ai_design_outputs table ────────────────────────────
  // Reached when the S24 migration has not been applied (local CI, test env).
  logger.warn(
    { studioId, rpcError: rpcError?.message },
    'ai-assist-budget: RPC not available — falling back to ai_design_outputs',
  )

  const todayUtcStart = new Date()
  todayUtcStart.setUTCHours(0, 0, 0, 0)

  const { data: legacyData, error: legacyError } = await supabase
    .from('ai_design_outputs')
    .select('cost_cents')
    .eq('studio_id', studioId)
    .gte('created_at', todayUtcStart.toISOString())

  if (legacyError) {
    throw new Error(`AI assist budget check failed (fallback): ${legacyError.message}`)
  }

  const usedToday = (legacyData ?? []).reduce((s, r) => s + (r.cost_cents ?? 0), 0)
  const cap = DAILY_CAP_CENTS_PER_STUDIO
  const remaining = cap - usedToday - estimatedCostCents

  if (remaining < 0) {
    throw new AiBudgetExceededError(studioId, usedToday, cap)
  }

  return { remaining, capCents: cap }
}

// ---------------------------------------------------------------------------
// S24: Record AI cost via service-role RPC
// ---------------------------------------------------------------------------

/**
 * Record AI job cost to ai_costs table via service-role RPC.
 * Must be called with a service-role client — ai_costs has no direct-write RLS.
 *
 * @param supabase — MUST be service-role client (bypasses RLS)
 * @param args — see RecordAiCostArgs in contracts.ts
 */
export async function recordAiCost(
  supabase: SupabaseClient,
  args: RecordAiCostArgs,
): Promise<RecordAiCostResult> {
  const { data, error } = await supabase.rpc(AI_RPC.RECORD_AI_COST, args)

  if (error) {
    logger.error({ err: error, args }, 'ai-budget: record_ai_cost RPC failed')
    throw new Error(`recordAiCost failed: ${error.message}`)
  }

  return data as RecordAiCostResult
}

// ---------------------------------------------------------------------------
// Utility (unchanged — preserved for all callers)
// ---------------------------------------------------------------------------

/** ISO timestamp of next UTC midnight — for reset time hints in API responses */
export function nextUtcMidnight(): string {
  const d = new Date()
  d.setUTCDate(d.getUTCDate() + 1)
  d.setUTCHours(0, 0, 0, 0)
  return d.toISOString()
}

