 *
 * S24 scaffold. Full implementation ships in S25.
 * Processes 'generate-ai-reply-draft' jobs from the 'inkos-jobs' queue.
 *
 * Job flow (S25):
 *   1. Load ai_jobs row — verify status='pending', set to 'processing'.
 *   2. Fetch conversation thread + artist voice profile.
 *   3. Call Claude (via flash-vision or direct Anthropic SDK).
 *   4. Insert ai_drafts row with status='pending' (never 'sent' directly).
 *   5. Update ai_jobs.status='done', record cost via recordAiCost().
 */
import { Worker } from 'bullmq'
import { logger } from '../lib/logger'
import { workerEnv } from '../lib/env'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'generate-ai-reply-draft'

// ─── Payload type ────────────────────────────────────────────────────────────

interface GenerateAiReplyDraftPayload {
  jobId: string
  studioId: string
  conversationId: string
  artistId?: string
}

function isGenerateAiReplyDraftPayload(data: unknown): data is GenerateAiReplyDraftPayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['jobId'] === 'string' &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string' &&
    typeof (data as Record<string, unknown>)['conversationId'] === 'string'
  )
}

// ─── Worker factory ──────────────────────────────────────────────────────────

export function createGenerateAiReplyDraftWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isGenerateAiReplyDraftPayload(job.data)) {
        logger.error(
          { jobId: job.id, data: job.data },
          'generate-ai-reply-draft: invalid payload shape — skipping',
        )
        return
      }

      const { jobId, studioId } = job.data
      logger.info({ job: JOB_NAME, jobId, studioId }, 'generate-ai-reply-draft: received')

      // S25: NOT_YET_IMPLEMENTED — full Claude integration ships in Sprint 25.
      throw new Error('S25: NOT_YET_IMPLEMENTED')
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 2,
    },
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id, jobName: job.name }, 'generate-ai-reply-draft worker: completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'generate-ai-reply-draft worker: failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'generate-ai-reply-draft worker: worker error')
  })

  return worker
}

